"""Recreate the 1.0.5 repair report from recorded fixes and release verification."""
from pathlib import Path
from html import escape
import json

HERE = Path(__file__).resolve().parent
fixes = json.loads((HERE / 'fixes.json').read_text(encoding='utf-8'))
release = json.loads((HERE / 'release.json').read_text(encoding='utf-8'))
tests = json.loads((HERE / 'fix-test-results.json').read_text(encoding='utf-8'))
passed = tests['numPassedTests']
md = ['# What’s Cooking 1.0.5 — high and medium issues fixed', '',
      'All 17 findings from the 18 October usability review are fixed: **7 High and 10 Medium**.', '',
      f"Live app: [whatscooking.expo.app]({release['productionUrl']}). Deployment: `{release['identifier']}`. Public reload verified against `{release['webBundle']}`.", '',
      f"Validation: **{passed} automated tests passed across 10 suites**, typecheck and lint passed, and Android, iOS and web production exports succeeded. Browser interaction checks used synthetic households at 390×844 and 360×800.", '',
      '## Repairs and verification', '', '| Finding | Change | Verification |', '|---|---|---|']
for f in fixes:
    md.append(f"| {f['id']} · {f['priority']} · {f['area']} | {f['change']} | {f['verification']} [Evidence](fixes/{f['evidence']}) |")
md += ['', '## Scope and remaining checks', '',
       'These are implementation and expert walkthrough results, not recruited-participant research. No physical Android/iPhone install or device screen reader was tested. Native exports confirm that the app bundles, not that every device behaviour is correct.', '',
       'No real messages, orders, personal photographs, real AI keys or paid AI calls were used. Saved allergy instructions are carried into the handoff; this does not certify every recipe’s allergen metadata. A knowledgeable food reviewer and native speakers should still check the catalogue and translations.', '',
       'Deferred family sync, invites and sign-in remain covered by the separate family-sync plan. This report closes UX01–UX17, not every requirement in the original FSD audit.', '',
       '## Evidence', '',
       '- [All test results](fix-test-results.json)',
       '- [Browser checks and limits](fixes/manual-checks.json)',
       '- [Small-phone action measurements](fixes/phone-layout.json)',
       '- [Exact release record](release.json)',
       '- [Original usability review](UX-review.md)',
       '- [Reusable participant test pack](Participant-test-pack.md)', '']
(HERE / 'Fixes.md').write_text('\n'.join(md), encoding='utf-8')
cards = []
for f in fixes:
    cards.append(f"""<article data-priority="{f['priority']}"><div class="line"><span class="status">Fixed</span><span>{f['id']} · {f['priority']}</span></div><h2>{escape(f['area'])}</h2><p>{escape(f['change'])}</p><details><summary>How it was checked</summary><p>{escape(f['verification'])}</p><a href="fixes/{escape(f['evidence'])}">Open evidence</a></details></article>""")
page = f"""<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>What’s Cooking · 1.0.5 fixes</title><style>
:root{{color-scheme:light;--ink:#243e31;--paper:#faf7f0;--line:#d9dfd3}}*{{box-sizing:border-box}}body{{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,sans-serif}}main{{max-width:1100px;margin:auto;padding:45px 24px}}h1{{font:clamp(38px,6vw,70px)/1.08 Georgia,serif;max-width:800px;margin:16px 0}}h2{{font-size:22px;margin:12px 0}}.eyebrow{{font-size:13px;letter-spacing:.13em;font-weight:800}}.lead{{font-size:20px;max-width:780px}}.stats{{display:flex;flex-wrap:wrap;gap:14px;margin:26px 0}}.stat{{flex:1;min-width:140px;border:1px solid var(--line);padding:18px;border-radius:15px;background:#fff}}.stat strong{{font-size:33px;display:block}}a{{color:#985033;text-underline-offset:3px}}nav{{display:flex;flex-wrap:wrap;gap:18px;margin:24px 0}}.note{{padding:18px 22px;background:#edf1e4;border-radius:15px;margin:24px 0}}.grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}}article{{padding:24px;border:1px solid var(--line);border-radius:17px;background:#fff}}article[hidden]{{display:none}}.line{{display:flex;gap:12px;font-size:13px;align-items:center}}.status{{padding:3px 10px;background:#deedda;border-radius:30px;font-weight:750}}summary{{cursor:pointer;font-weight:700;min-height:48px;display:flex;align-items:center}}.filter{{display:flex;gap:8px;flex-wrap:wrap;margin:25px 0}}button{{min-height:48px;padding:8px 20px;border:1px solid var(--line);border-radius:99px;color:var(--ink);background:white;font:inherit;cursor:pointer}}button[aria-pressed=true]{{background:var(--ink);color:white}}code{{overflow-wrap:anywhere}}.gallery{{display:grid;grid-template-columns:1fr 1fr;gap:20px}}figure{{margin:0}}img{{max-width:100%;max-height:620px;object-fit:contain;border:1px solid var(--line);border-radius:12px}}footer{{border-top:1px solid var(--line);padding-top:24px;margin-top:40px;font-size:14px}}@media(max-width:650px){{main{{padding:24px 16px}}.grid{{grid-template-columns:1fr}}.gallery{{grid-template-columns:1fr}}}}@media print{{button{{display:none}}article{{break-inside:avoid}}}}
</style><main><div class="eyebrow">WHAT’S COOKING · VERSION 1.0.5 · 18 OCTOBER 2026</div><h1>17 reviewed issues fixed.</h1><p class="lead">Meal records that remember who ate. Shopping that remembers what you bought. Clearer planning, setup and cook handoffs.</p><div class="stats"><div class="stat"><strong>7 / 7</strong>High issues fixed</div><div class="stat"><strong>10 / 10</strong>Medium issues fixed</div><div class="stat"><strong>{passed}</strong>Tests passed</div><div class="stat"><strong>3</strong>Platforms exported</div></div><nav><a href="{release['productionUrl']}">Open the live app</a><a href="Fixes.md">Written repair report</a><a href="release.json">Release verification</a><a href="Review.html">Original findings</a></nav><div class="note"><strong>Published and checked after reload.</strong><br>Version 1.0.5 · deployment <code>{release['identifier']}</code>. The public app serves the tested web bundle. Android and iPhone bundles exported successfully; physical phone testing remains to be done.</div><div class="filter" aria-label="Filter repaired findings"><button data-p="All" aria-pressed="true">All 17</button><button data-p="High" aria-pressed="false">High · 7</button><button data-p="Medium" aria-pressed="false">Medium · 10</button></div><section class="grid">{''.join(cards)}</section><h2>Visible changes</h2><div class="gallery"><figure><img src="fixes/06-cook-handoff.png" alt="Cook handoff with allergy notes and a persistent send action"><figcaption>Dietary notes and the primary handoff action fit the phone screen.</figcaption></figure><figure><img src="fixes/08-short-child-setup.png" alt="Short child setup form with a fixed save button"><figcaption>Start with essentials; extra preferences can wait.</figcaption></figure></div><footer><p>Typecheck and lint passed. Automated results, browser observations, measurements and screenshots are stored beside this report. Expert walkthrough with synthetic data; no recruited participants, physical-device certification or real messages/orders/AI keys. Recipe metadata and translations still need knowledgeable human review. Deferred family sync, invites and sign-in remain outside these 17 fixes.</p><nav><a href="fix-test-results.json">Automated results</a><a href="fixes/manual-checks.json">Browser checks</a><a href="Participant-test-pack.md">Participant test pack</a></nav></footer></main><script>document.querySelectorAll('button[data-p]').forEach(b=>b.addEventListener('click',()=>{{document.querySelectorAll('button[data-p]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('article').forEach(x=>x.hidden=b.dataset.p!=='All'&&x.dataset.priority!==b.dataset.p)}}));</script></html>"""
(HERE / 'Fixes.html').write_text(page, encoding='utf-8')
